from pathlib import Path
import sys
import tempfile
import unittest


SCRIPT_DIR = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(SCRIPT_DIR))

from lib import canonicalize_headers


GENERATED_FILES = (
	"core/include/PxAutoGeneratedMetaDataObjectNames.h",
	"core/include/PxAutoGeneratedMetaDataObjects.h",
	"core/src/PxAutoGeneratedMetaDataObjects.cpp",
	"extensions/include/PxExtensionAutoGeneratedMetaDataObjectNames.h",
	"extensions/include/PxExtensionAutoGeneratedMetaDataObjects.h",
	"extensions/src/PxExtensionAutoGeneratedMetaDataObjects.cpp",
)
CANONICAL_LINES = (
	b"// Copyright (c) 2001-2004 NovodeX AG. All rights reserved.",
	b"// Copyright (c) 2004-2008 AGEIA Technologies, Inc. All rights reserved.",
	b"// SPDX-FileCopyrightText: Copyright (c) 2008-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.",
	b"// SPDX-License-Identifier: Apache-2.0",
)
LEGACY_GENERATED_LINES = (
	CANONICAL_LINES[2],
	CANONICAL_LINES[3],
	CANONICAL_LINES[1],
	CANONICAL_LINES[0],
)
BODY = (
	canonicalize_headers.AUTOGENERATED_MARKER
	+ b"\n// generated body\n"
)


class CanonicalizeHeadersTest(unittest.TestCase):
	def setUp(self):
		self.temp_dir = tempfile.TemporaryDirectory()
		self.root = Path(self.temp_dir.name)
		self.template = self.root / "boilerplate.txt"
		self.template.write_bytes(b"\n".join(CANONICAL_LINES))

	def tearDown(self):
		self.temp_dir.cleanup()

	def _write_files(self, preamble_lines, newline=b"\n"):
		for relative in GENERATED_FILES:
			path = self.root / relative
			path.parent.mkdir(parents=True, exist_ok=True)
			preamble = newline.join(preamble_lines)
			body = BODY.replace(b"\n", newline)
			path.write_bytes(preamble + newline + newline + body)

	def _expected(self, newline):
		return (
			newline.join(CANONICAL_LINES)
			+ newline
			+ newline
			+ BODY.replace(b"\n", newline)
		)

	def test_canonicalizes_legacy_order_with_lf(self):
		self._write_files(LEGACY_GENERATED_LINES)

		canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		for relative in GENERATED_FILES:
			self.assertEqual((self.root / relative).read_bytes(), self._expected(b"\n"))

	def test_canonicalizes_legacy_order_with_crlf(self):
		self._write_files(LEGACY_GENERATED_LINES, b"\r\n")

		canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		for relative in GENERATED_FILES:
			self.assertEqual((self.root / relative).read_bytes(), self._expected(b"\r\n"))

	def test_canonical_output_is_unchanged(self):
		self._write_files(CANONICAL_LINES)
		before = {
			relative: (self.root / relative).read_bytes()
			for relative in GENERATED_FILES
		}

		canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		for relative in GENERATED_FILES:
			self.assertEqual((self.root / relative).read_bytes(), before[relative])

	def test_rejects_unexpected_preamble(self):
		self._write_files((b"// unexpected",))

		with self.assertRaisesRegex(RuntimeError, "unexpected generated copyright preamble"):
			canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

	def test_validation_failure_does_not_partially_rewrite_files(self):
		self._write_files(LEGACY_GENERATED_LINES)
		first = self.root / GENERATED_FILES[0]
		first_before = first.read_bytes()
		later = self.root / GENERATED_FILES[-1]
		later.write_bytes(b"// unexpected\n" + BODY)

		with self.assertRaisesRegex(RuntimeError, "unexpected generated copyright preamble"):
			canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		self.assertEqual(first.read_bytes(), first_before)

	def test_rejects_empty_output(self):
		with self.assertRaisesRegex(RuntimeError, "no generated metadata files found"):
			canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

	def test_canonicalizes_discovered_user_output(self):
		self._write_files(CANONICAL_LINES)
		user_output = self.root / "include/PxUserAutoGeneratedMetaDataObjects.h"
		user_output.parent.mkdir(parents=True, exist_ok=True)
		user_output.write_bytes(b"\n".join(LEGACY_GENERATED_LINES) + b"\n\n" + BODY)

		canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		self.assertEqual(user_output.read_bytes(), self._expected(b"\n"))

	def test_leaves_non_generated_files_untouched(self):
		self._write_files(LEGACY_GENERATED_LINES)
		other = self.root / "core/include/Other.h"
		other.write_bytes(b"unchanged\n")

		canonicalize_headers.canonicalize_generated_headers(self.root, self.template)

		self.assertEqual(other.read_bytes(), b"unchanged\n")


if __name__ == "__main__":
	unittest.main()
